function ensureMeta(name,attr='name'){
  let el=document.head.querySelector(`meta[${attr}="${name}"]`);if(!el){el=document.createElement('meta');el.setAttribute(attr,name);document.head.append(el)}return el;
}
function setMeta({title='Xanh Sky First',description='Xanh Sky First — thông tin, cơ hội tham gia và tài nguyên về môi trường và cộng đồng.',image='/assets/xanh-sky-first-logo.png',robots='index,follow',canonical=location.href.split('?')[0]}={}){
  document.title=title;
  ensureMeta('description').content=description;
  ensureMeta('robots').content=robots;
  const safeImage=safeImageSrc(image);
  let canonicalUrl;try{canonicalUrl=new URL(safeHref(canonical,location.origin+'/'),location.origin);if(canonicalUrl.origin!==location.origin)canonicalUrl=new URL(location.pathname,location.origin)}catch{canonicalUrl=new URL(location.pathname,location.origin)}
  canonicalUrl.search='';canonicalUrl.hash='';
  const pairs=[['og:title',title],['og:description',description],['og:image',new URL(safeImage,location.origin).href],['og:url',canonicalUrl.href],['og:type','website']];
  pairs.forEach(([n,v])=>ensureMeta(n,'property').content=v);
  let link=document.head.querySelector('link[rel="canonical"]');if(!link){link=document.createElement('link');link.rel='canonical';document.head.append(link)}link.href=canonicalUrl.href;
}

