function countdownBlockMarkup(b={},formId=null,openFormOnZero=false){
  const tz=b.timezone||'Asia/Ho_Chi_Minh',end=zonedLocalToISO(b.end_at,tz),start=b.start_at?zonedLocalToISO(b.start_at,tz):null;
  if(!end)return formId?'<div class="inline-status info">Biểu mẫu chưa cấu hình thời hạn hợp lệ.</div>':'';
  const href=safeHref(b.href||'', ''),label=String(b.label||'Đăng ký ngay'),warningHours=Math.max(0,Math.min(720,Number(b.warning_threshold_hours)||0));
  return `<section class="countdown-block" data-countdown data-countdown-start="${esc(start||'')}" data-countdown-end="${esc(end)}" data-countdown-before="${esc(b.before_text||'Chưa đến thời gian bắt đầu.') }" data-countdown-warning="${esc(b.warning_text||'Sắp hết hạn đăng ký.') }" data-countdown-warning-hours="${warningHours}" data-countdown-expired="${esc(b.expired_text||'Thời hạn đăng ký đã kết thúc.') }" ${formId?`data-countdown-close-form="${esc(formId)}"`:''} ${openFormOnZero?'data-countdown-open-form="1"':''} aria-live="polite"><div class="countdown-copy"><span class="eyebrow">${esc(b.kicker||'THỜI HẠN')}</span><h3>${esc(b.title||'Thời gian còn lại')}</h3>${b.body?`<p>${esc(b.body)}</p>`:''}<p class="countdown-phase-message" data-countdown-phase-message hidden></p><p class="countdown-expired-message" hidden>${esc(b.expired_text||'Thời hạn đăng ký đã kết thúc.')}</p>${formId?'':(href?`<a class="btn primary countdown-cta" href="${esc(href)}" ${isInternalHref(href)?'data-nav':''}>${esc(label)}</a>`:'')}</div><div class="countdown-clock" role="timer" aria-label="Thời gian còn lại"><div><strong data-countdown-days>—</strong><span>Ngày</span></div><div><strong data-countdown-hours>—</strong><span>Giờ</span></div><div><strong data-countdown-minutes>—</strong><span>Phút</span></div><div><strong data-countdown-seconds>—</strong><span>Giây</span></div></div></section>`;
}
function initCountdowns(root=document){
  $$('[data-countdown]',root).forEach(box=>{
    if(box.dataset.countdownReady)return;box.dataset.countdownReady='1';
    const end=Date.parse(box.dataset.countdownEnd||''),start=box.dataset.countdownStart?Date.parse(box.dataset.countdownStart):null;
    if(!Number.isFinite(end)||(box.dataset.countdownStart&&!Number.isFinite(start))||(start!==null&&start>=end)){box.classList.add('countdown-invalid');return;}
    let timer=null;const phase=$('.countdown-phase-message',box),expiredMsg=$('.countdown-expired-message',box),hours=Math.max(0,Math.min(720,Number(box.dataset.countdownWarningHours)||0))*3600000;
    const setPhase=(name,message='')=>{box.classList.toggle('is-warning',name==='warning');box.classList.toggle('is-before-start',name==='before');if(phase){phase.textContent=message;phase.hidden=!message;}};
    const stop=()=>{if(timer){clearInterval(timer);timer=null;}};
    const write=(diff)=>{const safe=Math.max(0,diff),days=Math.floor(safe/86400000),leftDay=safe%86400000,hrs=Math.floor(leftDay/3600000),leftHour=leftDay%3600000,mins=Math.floor(leftHour/60000),secs=Math.floor((leftHour%60000)/1000);const put=(key,n)=>{const el=$(`[data-countdown-${key}]`,box);if(el)el.textContent=String(n).padStart(2,'0')};put('days',days);put('hours',hrs);put('minutes',mins);put('seconds',secs);};
    const tick=()=>{
      if(!box.isConnected){stop();return;}
      const now=Date.now();
      if(box.dataset.countdownOpenForm==='1'&&now>=end){stop();box.classList.add('is-opened');setPhase('opened','Biểu mẫu đã đến thời gian mở. Tải lại để bắt đầu đăng ký.');const wrap=box.querySelector('.countdown-copy');if(wrap&&!$('.countdown-refresh-form',wrap)){const b=document.createElement('button');b.type='button';b.className='btn primary countdown-refresh-form';b.textContent='Tải lại biểu mẫu';b.addEventListener('click',()=>go(location.pathname+location.search,true));wrap.append(b);}write(0);return;}
      if(now>=end){stop();box.classList.add('is-expired');setPhase('expired','');if(expiredMsg){expiredMsg.hidden=false;expiredMsg.textContent=box.dataset.countdownExpired||'Thời hạn đăng ký đã kết thúc.';}const cta=$('.countdown-cta',box);if(cta){cta.setAttribute('aria-disabled','true');cta.classList.add('is-disabled');cta.removeAttribute('href');cta.removeAttribute('data-nav');}const formId=box.dataset.countdownCloseForm;if(formId){const form=document.getElementById(formId);if(form){form.hidden=true;if(!form.previousElementSibling?.matches('.countdown-form-expired')){const note=document.createElement('div');note.className='inline-status error countdown-form-expired';note.setAttribute('role','status');note.textContent=box.dataset.countdownExpired||'Biểu mẫu đã hết hạn.';form.insertAdjacentElement('beforebegin',note);}}}write(0);return;}
      if(start!==null&&now<start){setPhase('before',box.dataset.countdownBefore||'Chưa đến thời gian bắt đầu.');write(start-now);return;}
      const diff=end-now;if(hours>0&&diff<=hours)setPhase('warning',box.dataset.countdownWarning||'Sắp hết hạn đăng ký.');else setPhase('normal','');write(diff);
    };
    tick();if(!box.classList.contains('is-expired')&&!box.classList.contains('is-opened'))timer=setInterval(tick,1000);
  });
}
function renderRichBlocks(blocks=[]){
  return blocks.map(b=>{
    const t=b.type||'paragraph';
    if(t==='heading')return `<h2>${esc(b.text||b.title||'')}</h2>`;
    if(t==='countdown')return countdownBlockMarkup(b);
    if(t==='image'&&Number.isInteger(Number(b.media_id))&&Number(b.media_id)>0)return `<figure class="article-image"><img src="${esc(safeImageSrc(`/api/media/${Number(b.media_id)}`))}" alt="${esc(b.alt||'')}" loading="lazy"><figcaption>${esc(b.caption||'')}</figcaption></figure>`;
    if(t==='gallery'&&Array.isArray(b.media_ids))return `<div class="article-gallery">${b.media_ids.filter(id=>Number.isInteger(Number(id))&&Number(id)>0).map(id=>`<img src="${esc(safeImageSrc(`/api/media/${Number(id)}`))}" alt="${esc(b.alt||'')}" loading="lazy">`).join('')}</div>`;
    if(t==='quote')return `<blockquote>${esc(b.text||'')}</blockquote>`;
    if(t==='callout')return `<aside class="callout"><b>${esc(b.title||'Ghi chú')}</b><p>${esc(b.text||'')}</p></aside>`;
    if(t==='cta'){const href=safeHref(b.href||'/tham-gia');return `<p class="content-cta"><a class="btn primary" ${isInternalHref(href)?'data-nav':''} href="${esc(href)}">${esc(b.label||'Tìm hiểu thêm')}</a></p>`;}
    if(t==='table'){const rows=Array.isArray(b.rows)?b.rows:[];return `<div class="simple-table">${rows.map(r=>`<div>${(Array.isArray(r)?r:[r]).map(c=>`<span>${esc(c)}</span>`).join('')}</div>`).join('')}</div>`}
    if(t==='stats'){const items=Array.isArray(b.items)?b.items:[];return `<div class="mini-stats">${items.map(x=>`<div><strong>${esc(x.value)}</strong><span>${esc(x.label)}</span></div>`).join('')}</div>`}
    if(t==='spacer')return `<div style="height:${Math.min(160,Math.max(16,Number(b.height||48)))}px"></div>`;
    return `<p>${esc(b.text||b.body||'')}</p>`;
  }).join('');
}
async function dynamicSection(type,kicker,title){
  const routePrefix={article:'tin-tuc',project:'du-an',activity:'hoat-dong',opportunity:'co-hoi',resource:'tai-nguyen',initiative:'sang-kien'}[type]||type;
  let items=[];try{items=((await api(`/api/public/content?type=${encodeURIComponent(type)}`)).items||[]).slice(0,3)}catch{return `<section class="section dynamic-feature dynamic-feature-${esc(type)}"><div class="dynamic-feature-copy"><span class="eyebrow">${esc(kicker||type)}</span><h2>${esc(title||'Nội dung mới')}</h2><p class="inline-status error">Chưa thể tải danh sách lúc này. Vui lòng tải lại trang để thử lại.</p><a class="inline-retry" href="/${routePrefix}" data-nav>Thử tải danh sách lần nữa →</a></div></section>`}
  const visual = type==='project' ? `<div class="section-visual project-visual" aria-hidden="true"><div class="visual-orbit"></div><div class="project-stack"><span class="project-block block-blue">Dự án<br>giáo dục</span><span class="project-block block-green">Dự án<br>cộng đồng</span><span class="project-block block-mint">Dự án<br>môi trường</span></div><div class="visual-plant"><i></i><i></i><b></b></div><span class="visual-chip chip-one">Môi trường</span><span class="visual-chip chip-two">Cộng đồng</span></div>` : type==='activity' ? `<div class="section-visual calendar-visual" aria-hidden="true"><div class="calendar-ring"></div><div class="calendar-sheet"><div class="calendar-binding"></div><strong>LỊCH HOẠT ĐỘNG</strong><div class="calendar-grid">${Array.from({length:21},(_,i)=>`<span class="${[3,8,14,18].includes(i)?'calendar-mark':''}"></span>`).join('')}</div></div><span class="visual-chip chip-one">Sự kiện</span><span class="visual-chip chip-two">Hoạt động cộng đồng</span></div>` : '';
  return `<section class="section dynamic-feature dynamic-feature-${esc(type)}"><div class="dynamic-feature-copy"><span class="eyebrow">${esc(kicker||type)}</span><h2>${esc(title||'Nội dung mới')}</h2><p class="dynamic-feature-lead">${type==='project'?'Theo dõi các chương trình và dự án đã được công bố, tìm hiểu mục tiêu và cách đồng hành phù hợp.':type==='activity'?'Cập nhật hoạt động hiện tại và sắp tới từ dữ liệu đã được công bố; kiểm tra thời gian và điều kiện tham gia tại từng nội dung.':'Khám phá những nội dung mới đã được công bố từ Xanh Sky First.'}</p><a data-nav class="btn primary" href="/${routePrefix}">${type==='project'?'Xem chương trình & dự án':type==='activity'?'Xem hoạt động':'Khám phá nội dung'} →</a></div>${visual}<div class="dynamic-feature-list">${items.length?items.map(x=>`<a data-nav class="story" href="/${routePrefix}/${encodeURIComponent(String(x.slug||''))}">${x.cover_url?`<img src="${esc(safeImageSrc(x.cover_url))}" alt="${esc(x.title)}" loading="lazy">`:'<div class="placeholder">XANH</div>'}<div><span class="eyebrow">${esc(x.category||type)}</span><h3>${esc(x.title)}</h3><p>${esc(x.excerpt||'')}</p></div></a>`).join(''):'<div class="empty">Nội dung mới sẽ sớm được cập nhật tại đây. Hãy quay lại để khám phá những thông tin và hoạt động mới nhất từ Xanh Sky First</div>'}</div></section>`;
}
