async function renderHomeBlock(b,impact){
  if(b.visible===false)return '';
  if(b.type==='hero')return heroFromBlock(b);
  if(b.type==='countdown')return countdownBlockMarkup(b);
  if(b.type==='rich')return `<section class="section split"><div><span class="eyebrow">${esc(b.kicker||'VỀ XANH')}</span><h2>${esc(b.title||'')}</h2></div><p class="lead">${esc(b.body||'')}</p></section>`;
  if(b.type==='cards')return `<section class="section"><span class="eyebrow">${esc(b.kicker||'')}</span><h2>${esc(b.title||'')}</h2>${cards(b.items||[])}</section>`;
  if(b.type==='feature_grid')return `<section class="section"><span class="eyebrow">${esc(b.kicker||'')}</span><h2>${esc(b.title||'')}</h2>${cards((b.items||[]).map(x=>typeof x==='string'?{title:x,body:'Một hướng hành động để cộng đồng lựa chọn theo nhu cầu, năng lực và điều kiện thực tế.'}:{title:x.title||'',body:x.body||'Một hướng hành động để cộng đồng lựa chọn theo nhu cầu, năng lực và điều kiện thực tế.'}))}</section>`;
  if(b.type==='dynamic')return await dynamicSection(b.source,b.kicker,b.title);
  if(b.type==='impact'){
    if(impact.loadError)return `<section class="impact"><div class="impact-intro"><span class="eyebrow">${esc(b.kicker||'DẤU ẤN XANH')}</span><h2>${esc(b.title||'Mỗi con số đại diện cho một hành động đã thực sự diễn ra.')}</h2><p class="impact-lead">${esc(b.body||'Chỉ hiển thị số liệu có nguồn và phương pháp ghi nhận rõ ràng.')}</p><p class="inline-status error">Chưa thể tải số liệu lúc này. Các số liệu sẽ không được hiển thị khi chưa thể xác minh nguồn dữ liệu.</p></div></section>`;
    const approvedMetrics=[
      {metric_key:'participants',label:'Tình nguyện viên tham gia',unit:'người',icon:'users',sort_order:1},
      {metric_key:'completed_activities',label:'Hoạt động môi trường',unit:'hoạt động',icon:'sprout',sort_order:2},
      {metric_key:'waste_tons',label:'Rác thải thu gom',unit:'tấn',icon:'recycle',sort_order:3},
      {metric_key:'completed_programs',label:'Chương trình đã triển khai',unit:'chương trình',icon:'clipboard-check',sort_order:4},
      {metric_key:'education_sessions',label:'Hoạt động giáo dục môi trường',unit:'buổi',icon:'book-open',sort_order:5},
      {metric_key:'green_points',label:'Điểm xanh được kết nối',unit:'điểm',icon:'map-pin',sort_order:6},
      {metric_key:'partner_units',label:'Đơn vị đồng hành',unit:'đơn vị',icon:'handshake',sort_order:7}
    ];
    const rawCounters=Array.isArray(impact.counters)?impact.counters:[];
    // Gracefully fill missing configuration rows while a deployment/migration is pending.
    // Values remain null; this fallback never invents public statistics.
    const mergedCounters=approvedMetrics.map(base=>{
      const saved=rawCounters.find(c=>c.metric_key===base.metric_key);
      return saved?{...base,...saved,unit:saved.unit===undefined||saved.unit===null?base.unit:saved.unit,icon:saved.icon||base.icon,label:saved.label||base.label,enabled:saved.enabled===undefined?true:saved.enabled,value:saved.value===undefined?null:saved.value}:{...base,enabled:true,value:null,description:'',decimal_places:0,duration_ms:1800,delay_ms:0};
    });
    const counters=mergedCounters.filter(c=>c.enabled===true||Number(c.enabled)===1).sort((a,b)=>Number(a.sort_order||0)-Number(b.sort_order||0));
    const metricCards=counters.map((c,i)=>{
      const hasValue=c.value!==null&&c.value!==undefined&&Number.isFinite(Number(c.value));
      const decimals=Math.max(0,Math.min(3,Number(c.decimal_places||0)));
      const attributes=hasValue?`data-count="${Number(c.value)}" data-start="0" data-duration="${Number(c.duration_ms||1800)}" data-delay="${Number(c.delay_ms||0)}" data-decimals="${decimals}" data-metric="${esc(c.metric_key)}"`:'';
      return `<article class="metric-card"><span class="metric-index">${String(i+1).padStart(2,'0')}</span><div class="metric-icon">${impactIconSvg(c.icon)}</div><div class="metric-value"><strong ${attributes}>${hasValue?'0':'—'}</strong>${c.unit?`<span class="metric-unit">${esc(c.unit)}</span>`:''}</div><span class="metric-label">${esc(c.label||c.metric_key)}</span>${c.description&&c.description!==c.label?`<small>${esc(c.description)}</small>`:''}<span class="metric-accent" aria-hidden="true"></span></article>`;
    }).join('');
    return `<section class="impact"><div class="impact-intro"><span class="eyebrow">${esc(b.kicker||'DẤU ẤN XANH')}</span><h2>${esc(b.title||'Mỗi con số đại diện cho một hành động đã thực sự diễn ra.')}</h2><p class="impact-lead">${esc(b.body||'Những con số này được tổng hợp từ các hoạt động thực tế của Xanh Sky First cùng cộng đồng, thể hiện nỗ lực chung vì môi trường xanh và một tương lai bền vững.')}</p></div><div class="metrics" aria-label="Các chỉ số Dấu ấn xanh">${metricCards||'<p class="impact-empty">Các chỉ số sẽ được công bố tại đây khi được bật trong Admin Tổng.</p>'}</div></section>`;
  }
  if(b.type==='cta'){const href=safeHref((b.href||'/tham-gia').replace(/^#tham-gia$/,'/tham-gia'));return `<section class="cta"><h2>${esc(b.title||'Không cần bắt đầu bằng điều lớn.')}</h2><p>${esc(b.body||'')}</p><a ${isInternalHref(href)?'data-nav':''} class="btn light" href="${esc(href)}">${esc(b.label||'Cùng hành động')} →</a></section>`;}
  return '';
}
async function home(){
  let impact={};try{const data=await api('/api/public/impact');impact={...(data.impact||{}),counters:Array.isArray(data.counters)?data.counters:[]}}catch{impact={loadError:true}}
  const blocks=state.site?.page?.blocks||[];let html='';for(const b of blocks)html+=await renderHomeBlock(b,impact);
  if(!html)html=heroFromBlock({})+`<section class="section home-paths"><div class="section-heading"><div><span class="eyebrow">BẮT ĐẦU TỪ ĐÂU?</span><h2>Tìm thông tin phù hợp, rồi quyết định bước tiếp theo.</h2></div><p>Website chỉ hiển thị những dự án, hoạt động và cơ hội đã được công bố. Hãy đọc kỹ điều kiện của từng nội dung trước khi đăng ký.</p></div><div class="action-path-grid"><a class="action-path" data-nav href="/du-an"><span>01</span><h3>Tìm hiểu dự án</h3><p>Xem mục tiêu, phạm vi và thông tin đã công bố.</p><b>Xem dự án →</b></a><a class="action-path" data-nav href="/hoat-dong"><span>02</span><h3>Theo dõi hoạt động</h3><p>Kiểm tra thời gian, địa điểm và trạng thái trước khi tham gia.</p><b>Xem hoạt động →</b></a><a class="action-path" data-nav href="/tai-nguyen"><span>03</span><h3>Đọc tài nguyên</h3><p>Tìm hướng dẫn và thông tin nền để hiểu vấn đề rõ hơn.</p><b>Mở thư viện →</b></a></div></section><section class="cta"><h2>Bạn cần hỏi trước khi tham gia?</h2><p>Gửi câu hỏi qua trang liên hệ để trao đổi thông tin cụ thể trước khi cung cấp hồ sơ.</p><a data-nav class="btn light" href="/lien-he">Liên hệ Xanh →</a></section>`;
  setMeta({title:state.site?.page?.seo?.title||'Xanh Sky First — thông tin, cơ hội và tài nguyên về môi trường, cộng đồng.',description:state.site?.page?.seo?.description||'Thông tin, cơ hội tham gia và tài nguyên về môi trường, cộng đồng và phát triển bền vững.'});
  return shell(html);
}
