function fieldHtml(x){
  const n=`f_${esc(x.id)}`,req=x.required?'required':''; const star=x.required?' <b class="req-mark">*</b>':' <small class="optional">(không bắt buộc)</small>';
  if(x.type==='section')return `<div class="form-section"><h3>${esc(x.label)}</h3><p>${esc(x.description||'')}</p></div>`;
  if(x.type==='textarea')return `<label>${esc(x.label)}${star}${x.description?`<small>${esc(x.description)}</small>`:''}<textarea name="${n}" ${req} placeholder="${esc(x.placeholder||'')}"></textarea></label>`;
  if(x.type==='select')return `<label>${esc(x.label)}${star}<select name="${n}" ${req}><option value="">— Chọn —</option>${(x.options||[]).map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`;
  if(x.type==='radio')return `<fieldset><legend>${esc(x.label)}${star}</legend>${(x.options||[]).map(o=>`<label class="choice"><input type="radio" name="${n}" value="${esc(o)}" ${req}> ${esc(o)}</label>`).join('')}</fieldset>`;
  if(x.type==='checkbox')return `<fieldset data-required-group="${x.required?esc(n):''}"><legend>${esc(x.label)}${star}</legend>${(x.options||[]).map(o=>`<label class="choice"><input type="checkbox" name="${n}" value="${esc(o)}"> ${esc(o)}</label>`).join('')}</fieldset>`;
  if(x.type==='consent')return `<label class="consent"><input type="checkbox" name="${n}" ${req}> <span>${esc(x.label)}${star}</span></label>`;
  if(x.type==='file')return `<label>${esc(x.label)}${star}${x.description?`<small>${esc(x.description)}</small>`:''}<input name="${n}" type="file" ${x.accept?`accept="${esc(x.accept)}"`:''} ${req}><small class="upload-status" data-for="${esc(x.id)}"></small></label>`;
  if(x.type==='signature')return `<div class="signature-field" data-signature="${esc(x.id)}"><label>${esc(x.label)}${star}</label>${x.description?`<small>${esc(x.description)}</small>`:''}<canvas width="900" height="260" aria-label="Vùng ký tên"></canvas><div class="signature-actions"><button class="btn glass signature-clear" type="button">Xóa chữ ký</button><small class="upload-status" data-for="${esc(x.id)}">Ký trực tiếp bằng chuột hoặc cảm ứng.</small></div><input type="hidden" name="${n}" data-signature-required="${x.required?'1':'0'}"></div>`;
  if(x.type==='rating'){const min=Number.isFinite(Number(x.min))?Number(x.min):1,max=Number.isFinite(Number(x.max))?Number(x.max):10;return `<label>${esc(x.label)}${star}<input name="${n}" type="range" min="${min}" max="${max}" value="${min}" ${req}><small>${min} – ${max}</small></label>`}
  const map={email:'email',phone:'tel',url:'url',date:'date',time:'time',datetime:'datetime-local',number:'number'}; const type=map[x.type]||'text';
  return `<label>${esc(x.label)}${star}${x.description?`<small>${esc(x.description)}</small>`:''}<input name="${n}" type="${type}" ${req} ${x.min!==undefined?`min="${esc(x.min)}"`:''} ${x.max!==undefined?`max="${esc(x.max)}"`:''} placeholder="${esc(x.placeholder||'')}"></label>`;
}
function wireSignatures(root=document){
  $$('.signature-field',root).forEach(box=>{const c=$('canvas',box),ctx=c.getContext('2d');ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';let drawing=false,dirty=false;const pos=e=>{const r=c.getBoundingClientRect(),t=e.touches?.[0]||e;return [(t.clientX-r.left)*(c.width/r.width),(t.clientY-r.top)*(c.height/r.height)]};const begin=e=>{e.preventDefault();drawing=true;dirty=true;const [x,y]=pos(e);ctx.beginPath();ctx.moveTo(x,y)};const move=e=>{if(!drawing)return;e.preventDefault();const [x,y]=pos(e);ctx.lineTo(x,y);ctx.stroke()};const end=()=>drawing=false;c.addEventListener('pointerdown',begin);c.addEventListener('pointermove',move);window.addEventListener('pointerup',end);$('.signature-clear',box).onclick=()=>{ctx.clearRect(0,0,c.width,c.height);dirty=false};box._signature={canvas:c,isDirty:()=>dirty};});
}
