async function uploadMedia(file,meta={}){
  const fd=new FormData();fd.append('file',file);if(meta.alt_text)fd.append('alt_text',meta.alt_text);if(meta.caption)fd.append('caption',meta.caption);if(meta.credit)fd.append('credit',meta.credit);if(meta.visibility)fd.append('visibility',meta.visibility);
  if(file.type.startsWith('image/')){try{const size=await new Promise((resolve,reject)=>{const img=new Image(),u=URL.createObjectURL(file);img.onload=()=>{resolve([img.naturalWidth,img.naturalHeight]);URL.revokeObjectURL(u)};img.onerror=reject;img.src=u});fd.append('width',size[0]);fd.append('height',size[1])}catch{}}
  return (await api('/api/admin/media',{method:'POST',body:fd})).item;
}
async function openMediaPicker({onSelect,imagesOnly=true,currentId=null}={}){
  let items=(await api('/api/admin/media')).items;items=items.filter(x=>x.visibility!=='private');if(imagesOnly)items=items.filter(x=>String(x.mime_type).startsWith('image/'));
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">MEDIA LIBRARY</span><h2>Chọn ảnh / tệp</h2></div><button class="icon-btn modal-close">×</button></div><div class="picker-tools"><input id="picker-search" placeholder="Tìm theo tên hoặc alt..."><label class="btn primary">＋ Tải lên<input id="picker-upload" type="file" ${imagesOnly?'accept="image/*"':''} hidden></label></div><div class="media-grid picker-grid">${items.map(x=>`<button type="button" class="media-choice ${Number(currentId)===Number(x.id)?'selected':''}" data-id="${x.id}"><span>${String(x.mime_type).startsWith('image/')?`<img src="${esc(safeImageSrc(x.url))}" alt="${esc(x.alt_text||x.filename)}" loading="lazy">`:'📄'}</span><b>${esc(x.filename)}</b><small>${esc(x.alt_text||'Chưa có alt')}</small></button>`).join('')||'<div class="empty">Chưa có media phù hợp.</div>'}</div>`,true);
  $('.modal-close',m).onclick=closeModal;
  $$('.media-choice',m).forEach(btn=>btn.onclick=()=>{const item=items.find(x=>String(x.id)===btn.dataset.id);onSelect?.(item);closeModal()});
  $('#picker-search',m).oninput=e=>{const q=e.target.value.toLowerCase();$$('.media-choice',m).forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q))};
  $('#picker-upload',m).onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const item=await uploadMedia(file,{alt_text:file.name.replace(/\.[^.]+$/,'')});toast('Đã tải lên R2');onSelect?.(item);closeModal()}catch(x){toast(x.message,'error')}};
}

