  $('.upload-photo',m).onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const item=await uploadMedia(f,{alt_text:form.name.value||f.name});hidden().value=item.id;$('.photo-picker>img,.photo-picker>.person-ph',form).outerHTML=`<img src="${esc(safeImageSrc(item.url))}" alt="${esc(item.alt_text||item.filename)}">`;toast('Ảnh đã tải lên R2')}catch(x){toast(x.message,'error')}};
