function navItemCard(item,i){return `<article class="nav-admin-card" data-root="${i}"><div class="nav-admin-row"><div class="nav-order"><button type="button" class="icon-btn nav-up" title="Lên">↑</button><button type="button" class="icon-btn nav-down" title="Xuống">↓</button></div><label class="nav-label-field">Tên menu lớn<input data-nav-field="label" data-root="${i}" value="${esc(item.label||'')}" required></label><label>Đường dẫn<input data-nav-field="href" data-root="${i}" value="${esc(item.href||'/')}"></label><label class="choice nav-visible"><input type="checkbox" data-nav-field="visible" data-root="${i}" ${item.visible!==false?'checked':''}> Hiển thị</label><button type="button" class="btn danger nav-remove" data-root="${i}">Xóa</button></div><div class="nav-children-head"><b>Menu nhỏ (${(item.children||[]).length})</b><button type="button" class="btn glass nav-add-child" data-root="${i}">＋ Thêm menu nhỏ</button></div><div class="nav-child-list">${(item.children||[]).map((ch,j)=>`<div class="nav-child-row" data-root="${i}" data-child="${j}"><span class="nav-child-dot">↳</span><label>Tên menu nhỏ<input data-nav-field="label" data-root="${i}" data-child="${j}" value="${esc(ch.label||'')}" required></label><label>Đường dẫn<input data-nav-field="href" data-root="${i}" data-child="${j}" value="${esc(ch.href||'/')}"></label><label class="choice"><input type="checkbox" data-nav-field="visible" data-root="${i}" data-child="${j}" ${ch.visible!==false?'checked':''}> Hiển thị</label><button type="button" class="link-btn nav-child-up" data-root="${i}" data-child="${j}">↑</button><button type="button" class="link-btn nav-child-down" data-root="${i}" data-child="${j}">↓</button><button type="button" class="link-btn nav-child-remove" data-root="${i}" data-child="${j}">Xóa</button></div>`).join('')}</div></article>`}
function drawNavigationItems(){const root=$('#nav-items-editor');if(!root)return;root.innerHTML=(state.navigationDraft.items||[]).map(navItemCard).join('')||'<div class="empty">Chưa có menu. Thêm menu lớn để bắt đầu.</div>';$$('[data-nav-field]',root).forEach(el=>{const update=()=>{const i=Number(el.dataset.root),j=el.dataset.child==null?null:Number(el.dataset.child),obj=j==null?state.navigationDraft.items[i]:state.navigationDraft.items[i].children[j];if(!obj)return;obj[el.dataset.navField]=el.type==='checkbox'?el.checked:el.value;state.dirty=true};el.addEventListener(el.type==='checkbox'?'change':'input',update)});$$('.nav-up',root).forEach(b=>b.onclick=()=>{const i=Number(b.closest('[data-root]').dataset.root),a=state.navigationDraft.items;if(i>0){[a[i-1],a[i]]=[a[i],a[i-1]];state.dirty=true;drawNavigationItems()}});$$('.nav-down',root).forEach(b=>b.onclick=()=>{const i=Number(b.closest('[data-root]').dataset.root),a=state.navigationDraft.items;if(i<a.length-1){[a[i+1],a[i]]=[a[i],a[i+1]];state.dirty=true;drawNavigationItems()}});$$('.nav-remove',root).forEach(b=>b.onclick=()=>{if(confirm('Xóa mục menu lớn này cùng các menu con?')){state.navigationDraft.items.splice(Number(b.dataset.root),1);state.dirty=true;drawNavigationItems()}});$$('.nav-add-child',root).forEach(b=>b.onclick=()=>{const i=Number(b.dataset.root),item=state.navigationDraft.items[i];item.children=item.children||[];item.children.push({id:`submenu-${Date.now()}`,label:'Menu nhỏ mới',href:'/noi-dung/trang-moi',visible:true});state.dirty=true;drawNavigationItems()});$$('.nav-child-remove',root).forEach(b=>b.onclick=()=>{const r=Number(b.dataset.root),c=Number(b.dataset.child);state.navigationDraft.items[r].children.splice(c,1);state.dirty=true;drawNavigationItems()});$$('.nav-child-up',root).forEach(b=>b.onclick=()=>{const r=Number(b.dataset.root),c=Number(b.dataset.child),a=state.navigationDraft.items[r].children;if(c>0){[a[c-1],a[c]]=[a[c],a[c-1]];state.dirty=true;drawNavigationItems()}});$$('.nav-child-down',root).forEach(b=>b.onclick=()=>{const r=Number(b.dataset.root),c=Number(b.dataset.child),a=state.navigationDraft.items[r].children;if(c<a.length-1){[a[c+1],a[c]]=[a[c],a[c+1]];drawNavigationItems()}})}
function parseFooterColumns(text){return String(text||'').split(/\n\s*---\s*\n/).map((chunk,i)=>{const lines=chunk.split('\n').map(x=>x.trim()).filter(Boolean);const title=lines.shift()||`Cột ${i+1}`;return {title,items:lines.map(line=>{const [label,...href]=line.split('|');return {label:(label||'').trim(),href:href.join('|').trim()}}).filter(x=>x.label&&x.href)}}).filter(x=>x.title)}
