function login(){
  setMeta({title:'Đăng nhập Management Center | Xanh Sky First',robots:'noindex,nofollow'});
  app.innerHTML=`<div class="login"><section><img src="/assets/xanh-sky-first-logo.png" alt="Xanh Sky First"><span class="eyebrow">XANH SKY FIRST</span><h1>Management<br>Center</h1><p>CMS, Media, dự án, con người, form, CRM và dữ liệu cộng đồng.</p></section><form id="login-form"><a data-nav href="/">← Về website</a><h2>Đăng nhập</h2><label>Email<input name="email" type="email" required></label><label>Mật khẩu<input name="password" type="password" required></label><button class="btn primary">Đăng nhập</button><button type="button" class="link-btn" id="forgot">Quên mật khẩu</button><a data-nav href="/setup">First-time Setup</a></form></div>`;
  $('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/auth/login',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});go('/admin')}catch(x){toast(x.message,'error')}};
  $('#forgot').onclick=()=>{const email=prompt('Nhập email tài khoản quản trị:');if(!email)return;api('/api/auth/request-reset',{method:'POST',body:{email}}).then(r=>toast(r.message)).catch(x=>toast(x.message,'error'))};
}
