  if(path==='/tra-cuu'){
    const lookupForm=$('#lookup-form');
    lookupForm?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),out=$('#lookup-result');out.innerHTML='<p>Đang tra cứu…</p>';try{const r=await api(`/api/public/submission-lookup?code=${encodeURIComponent(f.get('code')||'')}`),x=r.item;const labels={new:'Đã tiếp nhận',reviewing:'Đang xem xét',needs_info:'Cần bổ sung thông tin',approved:'Đã duyệt',rejected:'Không phù hợp',completed:'Đã hoàn tất'};out.innerHTML=`<div class="success"><h3>${esc(labels[x.status]||x.status)}</h3><p><b>Mã:</b> ${esc(x.code)}</p><p><b>Biểu mẫu:</b> ${esc(x.form_name)}</p><p><b>Gửi lúc:</b> ${date(x.created_at)}</p><p><b>Cập nhật:</b> ${date(x.updated_at)}</p></div>`}catch(x){out.innerHTML=`<div class="empty">${esc(x.message)}</div>`}});
    if(new URLSearchParams(location.search).get('code')) lookupForm?.requestSubmit();
  }
  if(path.startsWith('/tham-gia/'))$('#public-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=(await api(`/api/public/form?slug=${encodeURIComponent(path.split('/').pop())}`)).item,f=new FormData(e.target),answers={};try{for(const x of form.fields||[]){if(x.type==='section')continue;const n=`f_${x.id}`;if(x.type==='file'||x.type==='signature'){let file=x.type==='file'?f.get(n):null;if(x.type==='signature'){const box=$(`[data-signature="${CSS.escape(x.id)}"]`,e.target);if(box?._signature?.isDirty())file=await new Promise(ok=>box._signature.canvas.toBlob(b=>ok(new File([b],`signature-${x.id}.png`,{type:'image/png'})),'image/png'));if(x.required&&!file)throw new Error(`Vui lòng ký tại “${x.label}”.`)}if(file&&file.size){const fd=new FormData();fd.append('form_id',form.id);fd.append('field_id',x.id);fd.append('file',file);const up=(await api('/api/public/form-upload',{method:'POST',body:fd})).upload;answers[x.id]={upload_token:up.upload_token,filename:up.filename};const st=$(`[data-for="${CSS.escape(x.id)}"]`,e.target);if(st)st.textContent='Đã tải dữ liệu an toàn.'}continue}if(x.type==='checkbox'){answers[x.id]=f.getAll(n);if(x.required&&!answers[x.id].length)throw new Error(`Vui lòng chọn ít nhất một mục tại “${x.label}”.`)}else if(x.type==='consent')answers[x.id]=f.has(n);else answers[x.id]=f.get(n)}const r=await api('/api/public/form-submit',{method:'POST',body:{form_id:form.id,guardian_consent:f.has('guardian_consent'),answers}});e.target.innerHTML=`<div class="success"><h2>${esc(r.title||'Đã nhận hồ sơ')}</h2><p>${esc(r.message)}</p><p>Mã hồ sơ:</p><strong>${esc(r.code)}</strong></div>`}catch(x){toast(x.message,'error')}});
  const counters=$$('[data-count]');
  const runCounter=el=>{const target=Number(el.dataset.count),from=0,duration=Math.max(300,Math.min(12000,Number(el.dataset.duration||1800))),delay=Math.max(0,Math.min(5000,Number(el.dataset.delay||0))),decimal=Math.max(0,Math.min(3,Number(el.dataset.decimals||0))),numberFormat=new Intl.NumberFormat('vi-VN',{minimumFractionDigits:decimal,maximumFractionDigits:decimal});el.textContent=numberFormat.format(from);const begin=()=>{const start=performance.now();const tick=t=>{const p=Math.min(1,(t-start)/duration),eased=1-Math.pow(1-p,3),v=from+(target-from)*eased;el.textContent=numberFormat.format(p===1?target:v);if(p<1)requestAnimationFrame(tick);else{el.textContent=numberFormat.format(target);el.dataset.counted='true'}};requestAnimationFrame(tick)};if(matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=numberFormat.format(target);el.dataset.counted='true'}else setTimeout(begin,delay)};
